(()=>{'use strict';const $=s=>document.querySelector(s);
const modal=document.createElement('div');modal.className='modal';modal.id='effectModal';modal.innerHTML=`<div class="panel modal-shell"><header class="modal-shell-head"><div><h2>状態効果</h2><p>マークを見れば、いま何が起きているかわかります。</p></div></header><div class="modal-shell-body effect-list"><div class="effect-item"><i>☠</i><b>毒</b><span>敵のターン開始時、数字と同じダメージ。ダメージ後に数字が1減ります。自分の猛毒フグなどが敵へ与えます。</span></div><div class="effect-item"><i>💧</i><b>脱力</b><span>敵の攻撃ダメージが25%小さくなります。多段攻撃は1発ずつ25%減ります。敵が行動するたび、残り回数が1減ります。</span></div><div class="effect-item"><i>😫</i><b>弱体</b><span>この状態の敵が攻撃を受けると、ダメージが50%増えます。敵が行動するたび、残り回数が1減ります。</span></div><div class="effect-item"><i>🛡</i><b>ブロック</b><span>受けるダメージを数字の分だけ防ぎます。自分のターン開始時に0へ戻ります。</span></div><div class="effect-item"><i>🦔</i><b>トゲ</b><span>この状態の相手を攻撃すると、トゲの数だけ反撃ダメージを受けます。自分にブロックがあれば、先にブロックが減ります。</span></div><div class="effect-item"><i>🐚</i><b>防御力</b><span>防御カードを使うたび、得られるブロックが数字の分だけ増えます。その戦闘中は残ります。</span></div><div class="effect-item"><i>💪</i><b>攻撃力</b><span>攻撃カードで与えるダメージが数字の分だけ増えます。その戦闘中は残ります。</span></div><div class="effect-item"><i>⚔</i><b>攻撃予定</b><span>敵が次に与えるダメージです。「5×3」は5ダメージを3回受けます。</span></div></div><footer class="modal-shell-foot"><button class="btn" id="effectClose">閉じる</button></footer></div>`;document.body.appendChild(modal);
modal.querySelector('.effect-list')?.insertAdjacentHTML('beforeend','<div class="effect-item"><i>👁</i><b>特殊行動</b><span>金色の予告は敵のギミックです。潮圧・破砕・捕食・毒喰い・反応の効果が、行動前に表示されます。</span></div>');
function open(){modal.classList.add('on');window.applyFuri?.(modal)}function close(){modal.classList.remove('on')}document.addEventListener('click',e=>{if(e.target.closest('#effectView,.statusRow,.intent'))open();if(e.target.closest('#effectClose')||e.target===modal)close()});
let lastTurn='';const obs=new MutationObserver(ms=>{const enemy=$('#enemySprite'),ps=$('#playerSprite'),st=$('#enemyStatus')?.textContent||'';if(enemy)enemy.classList.toggle('poisoned',st.includes('☠'));for(const m of ms){if(m.type==='attributes'&&m.target===ps&&ps.classList.contains('playerHit')&&enemy){enemy.classList.remove('enemy-attack');void enemy.offsetWidth;enemy.classList.add('enemy-attack');setTimeout(()=>enemy.classList.remove('enemy-attack'),560)}}let g=window.getAbyssGame?.();if(g?.enemy){let key=g.turn+'-'+g.enemy.n;if(key!==lastTurn&&$('#battle')?.classList.contains('on')&&!$('#endTurn')?.disabled){lastTurn=key;let f=document.createElement('div');f.className='turn-flash';f.textContent=`ターン ${g.turn}`;document.body.appendChild(f);setTimeout(()=>f.remove(),800)}}});obs.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['class','disabled']});
const endButton=$('#endTurn');new MutationObserver(()=>{if(!endButton.disabled)return;setTimeout(()=>{let g=window.getAbyssGame?.();if(g?.enemy&&endButton.disabled){g.turnBusy=false;endButton.disabled=false}},2200)}).observe(endButton,{attributes:true,attributeFilter:['disabled']});
})();
